from pathlib import Path
from html.parser import HTMLParser
import hashlib, json, re

class Document(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.skip = 0
        self.parts = []
        self.links = set()
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style', 'template'):
            self.skip += 1
        if not self.skip and tag in ('a', 'p', 'li', 'tr', 'h1', 'h2', 'h3', 'br'):
            self.parts.append('\n')
        if not self.skip and tag == 'a':
            href = dict(attrs).get('href') or ''
            if href.startswith('/help/') and re.search(r'marketplace|activation|payout|prohibited|fees', href, re.I):
                self.links.add(href)
    def handle_endtag(self, tag):
        if tag in ('script', 'style', 'template') and self.skip:
            self.skip -= 1
        if not self.skip and tag in ('a', 'p', 'li', 'tr', 'h1', 'h2', 'h3'):
            self.parts.append('\n')
    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)

root = Path('products/services/catalogue-qa-digital-checkout')
pattern = re.compile(r'Canada|marketplace|payout|artificial intelligence|AI.generated|services|digital goods|digital products|prohibited|\d\s*%|\$0\.50|monthly|upfront|approval', re.I)
records = {}
for name in ('fees', 'supported-countries', 'prohibited-products', 'marketplace'):
    path = root / 'raw' / (name + '.html')
    raw = path.read_bytes()
    doc = Document()
    doc.feed(raw.decode('utf-8'))
    lines = [' '.join(line.split()) for line in ''.join(doc.parts).splitlines() if line.strip()]
    selected = set()
    for index, line in enumerate(lines):
        if pattern.search(line):
            selected.update(range(max(0, index - 1), min(len(lines), index + 2)))
    records[name] = {'artifact': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'excerpts': [{'line': i + 1, 'text': lines[i]} for i in sorted(selected)], 'official_documentation_links': sorted(doc.links)}
out = root / 'official-source-extract.json'
out.write_text(json.dumps(records, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print({name: {'sha256': record['sha256'], 'excerpt_count': len(record['excerpts'])} for name, record in json.loads(out.read_text(encoding='utf-8')).items()})
